import { useMemo } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { Badge } from '@/components/ui/badge'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { useSets } from '@/hooks/use-supabase'
import { MoreHorizontal, Play } from 'lucide-react'
import { motion } from 'framer-motion'
import { Button } from '@/components/ui/button'

const RecentPlaysTable = () => {
  const { data: sets } = useSets()

  const recentPlays = useMemo(() => {
    if (!sets) return []
    
    return sets.slice(0, 5).map((set, index) => ({
      id: set.id,
      title: set.title,
      artist: set.artists?.name || 'Unknown Artist',
      photo: set.artists?.photo_url,
      plays: Math.floor(Math.random() * 500) + 100,
      status: index < 2 ? 'Active' : index < 4 ? 'Trending' : 'New',
      date: new Date(set.release_date).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric'
      })
    }))
  }, [sets])

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active':
        return 'bg-white/20 text-white hover:bg-white/30'
      case 'Trending':
        return 'bg-white/20 text-white hover:bg-white/30'
      case 'New':
        return 'bg-white/10 text-white/70 hover:bg-white/20'
      default:
        return 'bg-white/5 text-white/50 hover:bg-white/10'
    }
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.2 }}
    >
      <Card className="border-white/10 bg-white/[0.03] backdrop-blur-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base font-semibold text-white">Recent Plays</CardTitle>
            <Button variant="ghost" size="sm" className="text-white/70 hover:text-white hover:bg-white/10 h-8">
              View All
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow className="border-white/5 hover:bg-transparent">
                <TableHead className="text-white/50 font-medium">Set</TableHead>
                <TableHead className="text-white/50 font-medium">Status</TableHead>
                <TableHead className="text-white/50 font-medium">Plays</TableHead>
                <TableHead className="text-white/50 font-medium text-right">Date</TableHead>
                <TableHead className="w-12"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {recentPlays.map((play, index) => (
                <TableRow 
                  key={play.id} 
                  className="border-white/5 hover:bg-white/[0.02] transition-colors"
                >
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <Avatar className="h-10 w-10 border border-white/10">
                        {play.photo && <AvatarImage src={play.photo} alt={play.artist} />}
                        <AvatarFallback className="bg-white/10 text-white/70">
                          <Play className="w-4 h-4" />
                        </AvatarFallback>
                      </Avatar>
                      <div className="min-w-0">
                        <div className="font-medium text-white text-sm truncate">
                          {play.title}
                        </div>
                        <div className="text-xs text-white/50 truncate">
                          {play.artist}
                        </div>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={`${getStatusColor(play.status)} border-none`}>
                      {play.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-white/70 font-mono text-sm">
                    {play.plays.toLocaleString()}
                  </TableCell>
                  <TableCell className="text-white/50 text-sm text-right">
                    {play.date}
                  </TableCell>
                  <TableCell>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 text-white/50 hover:text-white hover:bg-white/10"
                    >
                      <MoreHorizontal className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </motion.div>
  )
}

export default RecentPlaysTable
