import { useState, useMemo } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Calendar } from '@/components/ui/calendar'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { useOurWorkProjects } from '@/hooks/use-supabase'
import { Badge } from '@/components/ui/badge'
import { motion } from 'framer-motion'

const EventsCalendar = () => {
  const [date, setDate] = useState<Date | undefined>(new Date())
  const { data: projects } = useOurWorkProjects()

  const eventDates = useMemo(() => {
    if (!projects) return []
    return projects
      .filter(p => p.upcoming && p.date)
      .map(p => new Date(p.date!))
  }, [projects])

  const upcomingCount = projects?.filter(p => p.upcoming)?.length || 0

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <Card className="border-white/10 bg-white/[0.03] backdrop-blur-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base font-semibold text-white">Events Calendar</CardTitle>
            <Badge variant="outline" className="bg-white/10 border-white/20 text-white/80">
              {upcomingCount} Upcoming
            </Badge>
          </div>
        </CardHeader>
        <CardContent className="pb-4">
          <Calendar
            mode="single"
            selected={date}
            onSelect={setDate}
            className="rounded-md border-0 w-full"
            classNames={{
              months: "flex flex-col sm:flex-row space-y-4 sm:space-x-4 sm:space-y-0",
              month: "space-y-4 w-full",
              caption: "flex justify-between pt-1 relative items-center px-1",
              caption_label: "text-sm font-medium text-white",
              nav: "space-x-1 flex items-center",
              nav_button: "h-7 w-7 bg-transparent p-0 opacity-50 hover:opacity-100 text-white hover:bg-white/10 rounded-md transition-colors",
              nav_button_previous: "absolute left-1",
              nav_button_next: "absolute right-1",
              table: "w-full border-collapse space-y-1",
              head_row: "flex justify-between w-full",
              head_cell: "text-white/50 rounded-md w-9 font-normal text-[0.8rem]",
              row: "flex w-full mt-2 justify-between",
              cell: "text-center text-sm p-0 relative [&:has([aria-selected])]:bg-white/10 first:[&:has([aria-selected])]:rounded-l-md last:[&:has([aria-selected])]:rounded-r-md focus-within:relative focus-within:z-20",
              day: "h-9 w-9 p-0 font-normal text-white/70 hover:bg-white/10 hover:text-white rounded-md transition-colors aria-selected:opacity-100",
              day_selected: "bg-white text-black hover:bg-white hover:text-black focus:bg-white focus:text-black",
              day_today: "bg-white/5 text-white border border-white/20",
              day_outside: "text-white/30 opacity-50",
              day_disabled: "text-white/20",
              day_hidden: "invisible",
            }}
          />
        </CardContent>
      </Card>
    </motion.div>
  )
}

export default EventsCalendar
