import { useMemo } from 'react'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { TrendingUp, TrendingDown, Music, Users, Headphones } from 'lucide-react'
import { useSets, useArtists } from '@/hooks/use-supabase'
import { motion } from 'framer-motion'

const StatsWithChart = () => {
  const { data: sets } = useSets()
  const { data: artists } = useArtists()

  const stats = useMemo(() => {
    const totalPlays = sets?.length ? sets.length * 125 : 0
    const lastMonthPlays = Math.floor(totalPlays * 0.83)
    const growth = ((totalPlays - lastMonthPlays) / lastMonthPlays * 100).toFixed(1)

    const totalListeners = sets?.length ? sets.length * 48 : 0
    const lastMonthListeners = Math.floor(totalListeners * 0.92)
    const listenerGrowth = ((totalListeners - lastMonthListeners) / lastMonthListeners * 100).toFixed(1)

    const totalSets = sets?.length || 0
    const activeArtists = artists?.filter(a => a.featured)?.length || 0

    return {
      plays: { value: totalPlays, growth: Number(growth), previous: lastMonthPlays },
      listeners: { value: totalListeners, growth: Number(listenerGrowth), previous: lastMonthListeners },
      sets: { value: totalSets, growth: 12.5 },
      artists: { value: activeArtists, growth: 8.2 }
    }
  }, [sets, artists])

  const cards = [
    {
      title: 'Total Plays',
      value: stats.plays.value.toLocaleString(),
      change: `+${stats.plays.growth}%`,
      description: 'from last month',
      icon: Headphones,
      trend: stats.plays.growth > 0,
      chartData: [65, 72, 68, 85, 92, 88, 100]
    },
    {
      title: 'Active Listeners',
      value: `+${stats.listeners.value.toLocaleString()}`,
      change: `+${stats.listeners.growth}%`,
      description: 'from last month',
      icon: Users,
      trend: stats.listeners.growth > 0,
      chartData: [45, 52, 58, 65, 70, 78, 85]
    },
    {
      title: 'Total Sets',
      value: stats.sets.value.toString(),
      change: `+${stats.sets.growth}%`,
      description: 'growth this month',
      icon: Music,
      trend: true,
      chartData: [30, 35, 40, 45, 50, 55, 60]
    }
  ]

  return (
    <section className="w-full max-w-7xl mx-auto px-4 sm:px-6 py-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {cards.map((card, idx) => (
          <motion.div
            key={card.title}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, delay: idx * 0.1 }}
          >
            <Card className="border-white/10 bg-white/[0.03] backdrop-blur-sm hover:bg-white/[0.06] transition-all duration-300">
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <CardTitle className="text-sm font-medium text-white/70">
                    {card.title}
                  </CardTitle>
                  <card.icon className="w-4 h-4 text-white/50" />
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <div className="flex items-end justify-between">
                    <div>
                      <div className="text-2xl font-bold text-white">
                        {card.value}
                      </div>
                      <div className="flex items-center gap-1 mt-1">
                        {card.trend ? (
                          <TrendingUp className="w-3 h-3 text-white/70" />
                        ) : (
                          <TrendingDown className="w-3 h-3 text-white/50" />
                        )}
                        <span className={`text-xs ${card.trend ? 'text-white/70' : 'text-white/50'}`}>
                          {card.change} {card.description}
                        </span>
                      </div>
                    </div>
                  </div>
                  
                  {/* Mini chart */}
                  <div className="h-16 flex items-end gap-1">
                    {card.chartData.map((height, i) => (
                      <motion.div
                        key={i}
                        initial={{ height: 0 }}
                        animate={{ height: `${height}%` }}
                        transition={{ duration: 0.5, delay: idx * 0.1 + i * 0.05 }}
                        className="flex-1 bg-white/20 rounded-t-sm hover:bg-white/30 transition-colors"
                        style={{ minHeight: '8px' }}
                      />
                    ))}
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        ))}
      </div>
    </section>
  )
}

export default StatsWithChart
