import { useMemo } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { TrendingUp } from 'lucide-react'
import { motion } from 'framer-motion'
import { useSets } from '@/hooks/use-supabase'

const ActivityChart = () => {
  const { data: sets } = useSets()

  const chartData = useMemo(() => {
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    return days.map((day, i) => ({
      day,
      plays: Math.floor(Math.random() * 400) + 200,
      listeners: Math.floor(Math.random() * 150) + 100
    }))
  }, [sets])

  const maxValue = Math.max(...chartData.map(d => Math.max(d.plays, d.listeners)))

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.3 }}
    >
      <Card className="border-white/10 bg-white/[0.03] backdrop-blur-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-base font-semibold text-white">Activity Overview</CardTitle>
          <p className="text-xs text-white/50 mt-1">Your weekly engagement metrics</p>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Line Chart */}
            <div className="h-48 relative">
              {/* Grid lines */}
              <div className="absolute inset-0 flex flex-col justify-between">
                {[...Array(5)].map((_, i) => (
                  <div key={i} className="w-full border-t border-white/5" />
                ))}
              </div>

              {/* Chart lines */}
              <svg className="absolute inset-0 w-full h-full" preserveAspectRatio="none">
                {/* Plays line */}
                <motion.polyline
                  initial={{ pathLength: 0 }}
                  animate={{ pathLength: 1 }}
                  transition={{ duration: 1, delay: 0.3 }}
                  fill="none"
                  stroke="rgba(255,255,255,0.4)"
                  strokeWidth="2"
                  points={chartData.map((d, i) => 
                    `${(i / (chartData.length - 1)) * 100}%,${100 - (d.plays / maxValue) * 100}%`
                  ).join(' ')}
                />
                
                {/* Listeners line */}
                <motion.polyline
                  initial={{ pathLength: 0 }}
                  animate={{ pathLength: 1 }}
                  transition={{ duration: 1, delay: 0.4 }}
                  fill="none"
                  stroke="rgba(255,255,255,0.2)"
                  strokeWidth="2"
                  points={chartData.map((d, i) => 
                    `${(i / (chartData.length - 1)) * 100}%,${100 - (d.listeners / maxValue) * 100}%`
                  ).join(' ')}
                />

                {/* Data points - Plays */}
                {chartData.map((d, i) => (
                  <motion.circle
                    key={`plays-${i}`}
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    transition={{ duration: 0.3, delay: 0.5 + i * 0.05 }}
                    cx={`${(i / (chartData.length - 1)) * 100}%`}
                    cy={`${100 - (d.plays / maxValue) * 100}%`}
                    r="4"
                    fill="white"
                    className="hover:r-6 transition-all cursor-pointer"
                  />
                ))}
              </svg>
            </div>

            {/* X-axis labels */}
            <div className="flex justify-between px-1">
              {chartData.map((d) => (
                <span key={d.day} className="text-xs text-white/50">
                  {d.day}
                </span>
              ))}
            </div>

            {/* Legend */}
            <div className="flex items-center justify-center gap-6 pt-2">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-white/40" />
                <span className="text-xs text-white/60">Plays</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-white/20" />
                <span className="text-xs text-white/60">Listeners</span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  )
}

export default ActivityChart
