import { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Minus, Plus, Target } from 'lucide-react'
import { motion } from 'framer-motion'

const GoalTracker = () => {
  const [goal, setGoal] = useState(500)
  const currentValue = 387

  const weekData = [
    { day: 'Sun', value: 65 },
    { day: 'Mon', value: 45 },
    { day: 'Tue', value: 78 },
    { day: 'Wed', value: 52 },
    { day: 'Thu', value: 69 },
    { day: 'Fri', value: 43 },
    { day: 'Sat', value: 35 },
  ]

  const maxValue = Math.max(...weekData.map(d => d.value))

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.1 }}
    >
      <Card className="border-white/10 bg-white/[0.03] backdrop-blur-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base font-semibold text-white flex items-center gap-2">
              <Target className="w-4 h-4" />
              Listener Goal
            </CardTitle>
          </div>
          <p className="text-xs text-white/50 mt-1">Set your daily listener goal</p>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Goal Display */}
          <div className="flex items-center justify-center gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setGoal(Math.max(100, goal - 50))}
              className="h-10 w-10 rounded-full bg-white/5 hover:bg-white/10 text-white border-0"
            >
              <Minus className="h-4 w-4" />
            </Button>
            
            <div className="text-center">
              <div className="text-4xl font-bold text-white tabular-nums">
                {currentValue}
              </div>
              <div className="text-xs text-white/50 uppercase tracking-wider mt-1">
                LISTENERS/DAY
              </div>
            </div>

            <Button
              variant="ghost"
              size="icon"
              onClick={() => setGoal(goal + 50)}
              className="h-10 w-10 rounded-full bg-white/5 hover:bg-white/10 text-white border-0"
            >
              <Plus className="h-4 w-4" />
            </Button>
          </div>

          {/* Weekly Bar Chart */}
          <div className="space-y-2">
            <div className="flex items-end justify-between h-32 gap-2">
              {weekData.map((data, index) => (
                <div key={data.day} className="flex-1 flex flex-col items-center gap-2">
                  <motion.div
                    initial={{ height: 0 }}
                    animate={{ height: `${(data.value / maxValue) * 100}%` }}
                    transition={{ duration: 0.5, delay: index * 0.05 }}
                    className="w-full bg-white/20 rounded-t-md hover:bg-white/30 transition-colors relative"
                    style={{ minHeight: '20px' }}
                  />
                  <span className="text-xs text-white/50">{data.day}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Set Goal Button */}
          <Button 
            className="w-full bg-white hover:bg-white/90 text-black font-semibold h-10"
          >
            Set Goal to {goal}
          </Button>
        </CardContent>
      </Card>
    </motion.div>
  )
}

export default GoalTracker
